// CSD_RATIONALE_BEGIN
// Spider text-to-SQL with a single SQL span. We track the full generated text
// in `generated`, whether we are currently inside the unique constrained SQL
// block in `insideConstrainedOut`, and the SQL tokens accumulated between the
// delimiters in `currentConstrainedOut`. Outside the block we generate freely
// but bias toward opening the SQL span once the model is already near "<<";
// after the block is closed, we suppress reopening so the output contains at
// most one constrained span.
// 
// Inside the SQL block, we use parser-aware constrained decoding. If the
// current SQL prefix is already complete, we close immediately with `>>`.
// Otherwise we inspect parser-side signals (`ValidTokenCount`, `DeadEndDetection`,
// and `TopValidCandidates`) and softly boost promising valid next tokens before
// sampling. If the sampled token is parser-valid, we append it; if not, we fall
// back to `ConstrainedStep`, which chooses a valid continuation. This tracked
// state makes it easy to preserve parser validity and the suffix relation
// between the active SQL prefix and the end of the full generated output.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the unconstrained branch, appending a normal token keeps
//   `insideConstrainedOut` false, so the implication is vacuous. When we open
//   the constrained span, we append "<<" and set `currentConstrainedOut := []`;
//   `parser.IsValidPrefix([])` holds by the method precondition. In the
//   complete-prefix branch, `CloseConstrainedSpan` sets `insideConstrainedOut`
//   to false, again making the implication vacuous. In the in-span decoding
//   branch, the sampled-token subbranch calls `AppendConstrainedToken` only
//   after `IsTokenValidNext` returns true, and the fallback subbranch uses
//   `ConstrainedStep` followed by `AppendConstrainedToken`, so the new current
//   constrained prefix remains parser-valid.
// suffix: Outside the span, changing `generated` while keeping
//   `insideConstrainedOut == false` does not matter. Opening the span appends
//   "<<" but sets `currentConstrainedOut := []`, and the length-0 suffix of
//   `generated` is `[]`. `CloseConstrainedSpan` appends ">>" and resets the
//   current constrained prefix to `[]`, so the invariant is immediate. In the
//   append branches inside the span, `AppendConstrainedToken` appends the same
//   token to both `generated` and `currentConstrainedOut`, preserving the
//   suffix equality.
// cost: The unconstrained raw-sampling branch uses `ChooseNextToken` and then
//   manually increments `helpers.cost`; we also increment `steps` once, so
//   `helpers.cost <= steps` is preserved. `CloseConstrainedSpan` bumps helper
//   cost internally and we increment `steps` once in that branch. In the
//   in-span soft-sampling branch, `TopValidCandidates`, `ValidTokenCount`,
//   `DeadEndDetection`, and logit adjustments are non-bumping; the primitive
//   sample manually bumps `helpers.cost`, and the fallback `ConstrainedStep`
//   bumps internally. Each such branch also increments `steps` once, so the
//   accounting invariant remains true.
// progress: In every branch, `steps` increases by exactly 1. The unconstrained
//   branch appends at most one token to `generated`. The close branch appends
//   exactly one token delimiter step to the full output. The in-span append
//   branches append at most one token to `generated`. Therefore
//   `|generated| <= |generatedPrefix| + steps` is preserved throughout.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps := 0;
var openedCount := 0;
if insideConstrained {
  openedCount := 1;
} else {
  var i := 0;
  while i < |generatedPrefix|
    invariant 0 <= i <= |generatedPrefix|
    invariant 0 <= openedCount <= 1
    decreases |generatedPrefix| - i
  {
    if generatedPrefix[i] == "<<" {
      openedCount := 1;
    }
    i := i + 1;
  }
}

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant |generated| <= |generatedPrefix| + steps
  invariant cost == 0
  invariant helpers.cost <= steps
  invariant 0 <= openedCount <= 1
  invariant insideConstrainedOut ==> openedCount == 1
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    lm.GenerateLogits(prompt + generated);
    if openedCount == 0 {
      helpers.BoostTokenLogits(lm, ["<<"], 6.0);
    } else {
      helpers.PenalizeTokenLogits(lm, ["<<"], 100.0);
    }
    var top := helpers.GetHighestLogitToken(lm);
    var topLogit := helpers.GetTokenLogit(lm, top);
    var openLogit := helpers.GetTokenLogit(lm, "<<");
    var next := lm.ChooseNextToken();
    helpers.cost := helpers.cost + 1;
    steps := steps + 1;

    if next == eosToken {
      break;
    } else if openedCount == 0 && (next == "<<" || openLogit >= topLogit - 2.0) {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      openedCount := 1;
    } else {
      generated := generated + [next];
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);
    var candidates := helpers.TopValidCandidates(
      lm, parser, constrainedPrompt, currentConstrainedOut, 4, eosToken
    );

    lm.GenerateLogits(constrainedPrompt + currentConstrainedOut);
    if narrow {
      helpers.BoostTokenLogits(lm, candidates, 8.0);
    } else {
      helpers.BoostTokenLogits(lm, candidates, 4.0);
    }
    helpers.PenalizeTokenLogits(lm, [">>"], 100.0);
    if validCount == 1 {
      helpers.ScaleAllLogits(lm, 0.5);
    }

    var next := lm.ChooseNextTokenUnconstrained();
    helpers.cost := helpers.cost + 1;
    steps := steps + 1;

    if next == eosToken {
      break;
    } else {
      var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
      if valid {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      } else {
        var forcedNext := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
        if forcedNext == eosToken {
          break;
        } else {
          var appendedGenerated2, appendedInside2, appendedCurrent2 := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, forcedNext
          );
          generated := appendedGenerated2;
          insideConstrainedOut := appendedInside2;
          currentConstrainedOut := appendedCurrent2;
        }
      }
    }
  }
}

cost := steps;

